(()=>{
'use strict';const s=window.WordShapeProto,V=s.V;
function buildPyramid(){
 const A=[0,-2.15,0],B=[-2,1.35,2],C=[2,1.35,2],D=[2,1.35,-2],E=[-2,1.35,-2],faces=[[A,B,C],[A,C,D],[A,D,E],[A,E,B]],base=[[B,E,D],[B,D,C]];
 s.bodyFaces=[...faces,...base].map((verts,i)=>{let n=V.norm(V.cross(V.sub(verts[1],verts[0]),V.sub(verts[2],verts[0])));if(V.dot(n,s.center(verts))<0)n=V.mul(n,-1);return{verts,n,side:i<4}});
 const edgeMap=new Map(),N=4;
 faces.forEach((f,fi)=>{let[a,b,c]=f,n=V.norm(V.cross(V.sub(b,a),V.sub(c,a)));if(V.dot(n,s.center(f))<0)n=V.mul(n,-1);const B=s.basis(n,V.sub(c,b)),g=[],rg=[];for(let i=0;i<=N;i++){g[i]=[];rg[i]=[];for(let j=0;j<=N-i;j++){const u=i/N,v=j/N,p=V.add(V.add(V.mul(a,1-u-v),V.mul(b,u)),V.mul(c,v));g[i][j]=p;rg[i][j]=V.add(p,V.mul(n,.035))}}
  const add=(raw,ren)=>{const c0=s.center(ren),pp=s.shrink(ren,c0),e=s.ext(c0,pp,B.u,B.v),id=s.node({pos:c0,n,u:B.u,v:B.v,hu:e.hu,hv:e.hv,polygon:pp,physical:raw,region:fi});for(let k=0;k<3;k++){const ek=s.edge(raw[k],raw[(k+1)%3]);if(!edgeMap.has(ek))edgeMap.set(ek,[]);edgeMap.get(ek).push(id)}};
  for(let i=0;i<N;i++)for(let j=0;j<N-i;j++){add([g[i][j],g[i+1][j],g[i][j+1]],[rg[i][j],rg[i+1][j],rg[i][j+1]]);if(j<N-i-1)add([g[i+1][j],g[i+1][j+1],g[i][j+1]],[rg[i+1][j],rg[i+1][j+1],rg[i][j+1]])}
 });
 // Triangle navigation: only a complete shared edge is valid. Corner-only contact is rejected.
 for(const ids of edgeMap.values())for(let i=0;i<ids.length;i++)for(let j=i+1;j<ids.length;j++)s.link(ids[i],ids[j]);
}
function ico(){const t=(1+Math.sqrt(5))/2,vs=[[-1,t,0],[1,t,0],[-1,-t,0],[1,-t,0],[0,-1,t],[0,1,t],[0,-1,-t],[0,1,-t],[t,0,-1],[t,0,1],[-t,0,-1],[-t,0,1]].map(V.norm);let fs=[[0,11,5],[0,5,1],[0,1,7],[0,7,10],[0,10,11],[1,5,9],[5,11,4],[11,10,2],[10,7,6],[7,1,8],[3,9,4],[3,4,2],[3,2,6],[3,6,8],[3,8,9],[4,9,5],[2,4,11],[6,2,10],[8,6,7],[9,8,1]],cache=new Map(),mid=(a,b)=>{const k=a<b?a+':'+b:b+':'+a;if(cache.has(k))return cache.get(k);const id=vs.length;vs.push(V.norm(V.add(vs[a],vs[b])));cache.set(k,id);return id},out=[];for(const[a,b,c]of fs){const ab=mid(a,b),bc=mid(b,c),ca=mid(c,a);out.push([a,ab,ca],[b,bc,ab],[c,ca,bc],[ab,bc,ca])}return{vs,fs:out}}
function around(n,pts){const B=s.basis(n);return[...pts].sort((a,b)=>{const da=V.sub(a,V.mul(n,V.dot(a,n))),db=V.sub(b,V.mul(n,V.dot(b,n)));return Math.atan2(V.dot(da,B.v),V.dot(da,B.u))-Math.atan2(V.dot(db,B.v),V.dot(db,B.u))})}
function buildOrb(){const R=2.02,{vs,fs}=ico(),inc=Array.from({length:vs.length},()=>[]),es=new Set();fs.forEach(f=>{const c=V.norm(V.add(V.add(vs[f[0]],vs[f[1]]),vs[f[2]]));f.forEach(i=>inc[i].push(c));[[f[0],f[1]],[f[1],f[2]],[f[2],f[0]]].forEach(([a,b])=>es.add(a<b?a+':'+b:b+':'+a))});s.orbEdges=[...es].map(k=>k.split(':').map(Number));for(let i=0;i<vs.length;i++){const n=V.norm(vs[i]),raw=around(n,inc[i]).map(p=>V.mul(V.norm(p),R+.055)),c=V.mul(n,R+.055),pp=s.shrink(raw,c),B=s.basis(n,V.sub(pp[0],c)),e=s.ext(c,pp,B.u,B.v);s.node({pos:c,n,u:B.u,v:B.v,hu:e.hu,hv:e.hv,polygon:pp,physical:raw,region:0})}s.orbEdges.forEach(([a,b])=>s.link(a,b))}
s.cyl=(th,y,r)=>[Math.sin(th)*r,y,Math.cos(th)*r];s.mugR=y=>{const t=s.clamp((y+1.575)/3.15,0,1);return 1.60+(1.48-1.60)*t};
function buildMug(){const R=6,C=6;for(let r=0;r<R;r++)for(let c=0;c<C;c++){const t0=-.70+c*(1.40/C),t1=-.70+(c+1)*(1.40/C),tm=(t0+t1)/2,yt=-1.06+r*(2.12/R),yb=-1.06+(r+1)*(2.12/R),ym=(yt+yb)/2,n=[Math.sin(tm),0,Math.cos(tm)],p=s.cyl(tm,ym,s.mugR(ym)),raw=[s.cyl(t0,yt,s.mugR(yt)),s.cyl(t1,yt,s.mugR(yt)),s.cyl(t1,yb,s.mugR(yb)),s.cyl(t0,yb,s.mugR(yb))],pp=s.shrink(raw,p),B=s.basis(n,[Math.cos(tm),0,-Math.sin(tm)]),e=s.ext(p,pp,B.u,B.v);s.node({pos:p,n,u:B.u,v:B.v,hu:e.hu,hv:e.hv,polygon:pp,physical:raw,row:r,col:c,region:0,th:tm,y:ym})}for(let r=0;r<R;r++)for(let c=0;c<C;c++){const id=r*C+c;for(let dr=-1;dr<=1;dr++)for(let dc=-1;dc<=1;dc++){if(!dr&&!dc)continue;const rr=r+dr,cc=c+dc;if(rr>=0&&rr<R&&cc>=0&&cc<C)s.link(id,rr*C+cc)}}}
s.build=()=>{s.nodes.length=0;s.byId.clear();s.adj.clear();s.bodyFaces=[];s.orbEdges=[];s.mode==='pyramid'?buildPyramid():s.mode==='orb'?buildOrb():buildMug();s.ui.tiles.textContent=s.nodes.length;s.ui.route.textContent=s.cfg.route};
})();
